def normalize(path):
    if not path:
        return '.'

    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '.':
            continue
        elif part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                stack.append('..')
        elif part:
            stack.append(part)

    normalized_path = '/'.join(stack)

    if path.startswith('/'):
        if normalized_path == '':
            return '/'
        else:
            return '/' + normalized_path

    return normalized_path
```

