def strip_comments(code):
    lines = code.split('\n')
    result = []
    for line in lines:
        in_string = False
        new_line = ''
        i = 0
        while i < len(line):
            if line[i] == '"' and (i == 0 or line[i-1] != '\\'):
                in_string = not in_string
            if not in_string and line[i:i+2] == '#':
                break
            new_line += line[i]
            i += 1
        result.append(new_line)
    return '\n'.join(result)
```

