module.exports = function debounceCount(fn, ms) {
  let timeout;
  let callCount = 0;

  function debounced(...args) {
    clearTimeout(timeout);
    callCount++;
    timeout = setTimeout(() => {
      fn.call(this, ...args);
      callCount = 0;
    }, ms);
  }

  function flush() {
    if (timeout) {
      clearTimeout(timeout);
      fn.call(this);
      callCount = 0;
    }
  }

  return {
    call: debounced,
    flush: flush
  };
};
